// Number of Recent Calls using Sliding Window Queue
struct RecentCounter {
    var queue = AnimatedQueue<Int>()

    mutating func ping(_ t: Int) -> Int {
        queue.enqueue(t)
        while let oldest = queue.peek(), oldest < t - 3000 {
            queue.dequeue()
        }
        return queue.count
    }
}

var counter = RecentCounter()
let requests = [1, 100, 3001, 3002]
for req in requests {
    _ = counter.ping(req)
}
